"""Writes cases_spec.json: case id, kind, path, heading, target sentence (old text), source of truth."""
import json,random
from llm import W
P=json.load(open(W+"/pool.json")); CL=json.load(open(W+"/classify.json"))
def pick(path,head,n=0):
    r=[r for r in P if r["path"].endswith(path) and r["head"].lstrip("# 🔴🔑⛔").startswith(head)]
    assert len(r)>=1,(path,head); return r[n]
S=[]
def add(kind,name,path,head,target,source,res=False):
    r=pick(path,head); S.append(dict(case=kind+"_"+name,kind=kind,path=r["path"],base=r["base"],head=r["head"],target=target,source=source,reserve=res))
