for i in (3,6,10,18,20,21,22,27,29,30,32,34):
    o=CL[i]; 
    S.append(dict(case="STYLE_%02d"%i,kind="STYLE",path=o["path"],base=[r["base"] for r in P if r["path"]==o["path"]][0],head=o["head"],target=o["cls"]["target_sentence_in_A"],source="The old text is where the rule was first written; the key is its plain meaning. (Owner words inside the section count as the source.)",reserve=i in(32,34)))
ctl=[("designer_cleanse.md","What you write"),("designer_cleanse.md","You must not"),("2026-11-13-maturation-pipeline.md","Operations"),("2026-11-13-maturation-pipeline.md","The pipeline fixes"),("2026-11-13-maturation-pipeline.md","6. Flow"),("2026-11-13-maturation-pipeline.md","The twelve rules"),("2026-11-13-maturation-pipeline.md","The Designer's inner"),("2026-11-13-maturation-pipeline.md","The kept validation"),("2026-11-13-maturation-pipeline.md","What this map retires"),("LEXICON.md","The game and the proof"),("live-debugging-proof-harness/SKILL.md","Reference files")]
for n,(p,h) in enumerate(ctl):
    r=pick(p,h); assert r["old"]==r["new"],(p,h)
    S.append(dict(case="CONTROL_%02d"%n,kind="CONTROL",path=r["path"],base=r["base"],head=r["head"],target="(any one rule in the section that tells an agent to do or not to do something; you choose)",source="The section itself (the same in both arms).",reserve=n==10))
for s in S:
    r=[r for r in P if r["path"]==s["path"] and r["head"]==s["head"]][0]; s["old"],s["new"]=r["old"],r["new"]
json.dump(S,open("cases_spec.json","w"),indent=1,ensure_ascii=False)
for s in S: print(s["case"],len(s["old"].split()),len(s["new"].split()),s["head"][:40])
